def calc_weight(self):
    weight = (
        self.w_p
        @ (self.w_l * self.l_mask + self.l_eye)
        @ ((self.w_u * self.u_mask) + torch.diag(self.s_sign * torch.exp(self.w_s)))
    )

    return weight.unsqueeze(2).unsqueeze(3)

